-- Focused rollback-only test using the existing fictional local platform operator/Horizonte.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create temporary table fixture as select auth_user_id uid,'b2a00000-0000-4000-8000-000000000001'::uuid sid from persons where id='4d6b0000-0000-4000-8000-000000000001';
insert into auth.sessions(id,user_id,created_at,updated_at) select sid,uid,clock_timestamp(),clock_timestamp() from fixture;
select set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true) from fixture;
select public.pikas_session_start();
select public.platform_enter_sandbox_pov(gen_random_uuid(),'03e71159-69e9-4387-9b3b-65799d49faf0','b9496342-5079-46ae-83b8-05c39bcbd7fe','school_admin');
create function pg_temp.rows(p_code text) returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('source_row',2,'first_name','  Ana  ','last_name','Test','student_code',p_code,'starts_on',current_date::text,'location_id','cc7ca5f3-d27e-43ea-b3c9-8a6ef4e327d4','grade','  Primero  '));$$;
create function pg_temp.validate(p_rows jsonb) returns jsonb language sql as $$select public.school_student_bulk_validate('df8fcd98-6ece-4f87-b4e9-2f5f3ec8e488',p_rows);$$;
create function pg_temp.commit_batch(p_rows jsonb,p_key uuid default 'b2a00000-0000-4000-8000-000000000002',p_include integer[] default array[2]) returns jsonb language sql as $$select public.school_student_bulk_commit('df8fcd98-6ece-4f87-b4e9-2f5f3ec8e488',p_key,p_rows,p_include,true);$$;
set local role authenticated;
select is(pg_temp.validate(pg_temp.rows('B2A-VALID'))->>'valid','true','valid complete batch');
select is(pg_temp.validate(pg_temp.rows('B2A-VALID'))#>>'{rows,0,row,first_name}','Ana','names trimmed consistently');
select is(pg_temp.validate(pg_temp.rows('B2A-VALID'))#>>'{rows,0,row,grade}','Primero','placement labels trimmed');
select is(pg_temp.validate(pg_temp.rows('B2A-VALID')||jsonb_build_array(jsonb_build_object('source_row',9,'first_name','','last_name','Test','student_code','B2A-BAD','starts_on','2026-02-30')))->>'valid','false','invalid row rejects validation');
select is(pg_temp.validate(jsonb_set(pg_temp.rows('B2A-VALID'),'{0,starts_on}',to_jsonb((current_date+1)::text)))->>'valid','false','future enrollment denied');
select is(pg_temp.validate(pg_temp.rows('Case-Code')||jsonb_set(pg_temp.rows('  case-code  '),'{0,source_row}','9'))->>'valid','false','normalized duplicates are reported');
select is(pg_temp.validate(jsonb_set(pg_temp.rows('B2A-VALID'),'{0,location_id}','"00000000-0000-4000-8000-000000000099"'))->>'valid','false','unknown campus denied');
select is(pg_temp.validate(jsonb_set(pg_temp.rows('B2A-VALID'),'{0,location_id}','"not-uuid"'))->>'valid','false','malformed campus reported');
select is(pg_temp.validate(pg_temp.rows('B2A-VALID')-'unused')->>'school_id','df8fcd98-6ece-4f87-b4e9-2f5f3ec8e488','response school bound');
select throws_ok($q$select pg_temp.validate((select jsonb_agg(pg_temp.rows('X')->0) from generate_series(1,201)))$q$,'22023','student_bulk_row_limit','201 rows explicitly denied');
select throws_ok($q$select pg_temp.validate(jsonb_set(pg_temp.rows('X'),'{0,first_name}',to_jsonb(repeat('x',1048576))))$q$,'22023','student_bulk_payload_limit','MiB payload explicitly denied');
select throws_ok($q$select pg_temp.validate(pg_temp.rows('X')||pg_temp.rows('Y'))$q$,'22023','duplicate_source_row','duplicate source row identity denied');
select throws_ok($q$select public.school_student_bulk_commit('df8fcd98-6ece-4f87-b4e9-2f5f3ec8e488',gen_random_uuid(),pg_temp.rows('X'),array[2],false)$q$,'22023','invalid_confirmed_selection','explicit confirmation required');
select throws_ok($q$select pg_temp.commit_batch(pg_temp.rows('X'),gen_random_uuid(),array[3])$q$,'22023','invalid_confirmed_selection','unknown inclusion denied');
reset role;
create temporary table successful as select pg_temp.commit_batch(pg_temp.rows('B2A-CREATED')) result;
set local role authenticated;
select is(pg_temp.commit_batch(pg_temp.rows('B2A-CREATED'))->>'status','committed','exact completed retry returns success despite existing code');
select is(pg_temp.validate(pg_temp.rows('b2a-created'))#>>'{rows,0,errors,0}','existing_code','active conflict detected across code case');
select throws_ok($q$select pg_temp.commit_batch(pg_temp.rows('B2A-DIFFERENT'))$q$,'23505','student_bulk_request_conflict','request fingerprint mismatch denied');
select throws_ok($q$select * from pikas_private.student_bulk_requests$q$,'42501',null,'private journal inaccessible');
reset role;
select is(pg_temp.commit_batch(pg_temp.rows('B2A-CREATED')),(select result from successful),'retry returns identical IDs/result');
select is(pg_temp.commit_batch(jsonb_set(pg_temp.rows('B2A-CREATED'),'{0,first_name}','"Ana"')),(select result from successful),'equivalent trimmed payload has same canonical fingerprint');
select is((select count(*)::int from students where student_code='B2A-CREATED'),1,'retry creates exactly one student');
select is((select count(*)::int from student_enrollments where student_id=((select result from successful)#>>'{created,0,student_id}')::uuid),1,'one enrollment');
select is((select count(*)::int from student_campus_placements where enrollment_id=((select result from successful)#>>'{created,0,enrollment_id}')::uuid),1,'one placement');
select is((select p.auth_user_id from persons p join students s on s.person_id=p.id where s.student_code='B2A-CREATED'),null::uuid,'created Person has no Auth identity');
select is(pg_temp.commit_batch(pg_temp.rows('B2A-MIX')||jsonb_set(pg_temp.rows('B2A-CREATED'),'{0,source_row}','9'),gen_random_uuid(),array[2,9])->>'status','invalid','invalid included row rejects entire batch');
select is((select count(*)::int from students where student_code='B2A-MIX'),0,'valid row not written when another included row conflicts');
select is(pg_temp.commit_batch(pg_temp.rows('B2A-EXCLUDED')||jsonb_set(pg_temp.rows('B2A-CREATED'),'{0,source_row}','9'),gen_random_uuid(),array[2])->>'status','committed','explicit exclusion permits valid confirmed subset');
select is(pg_temp.commit_batch(pg_temp.rows('B2A-DUPE')||jsonb_set(pg_temp.rows('b2a-dupe'),'{0,source_row}','9'),gen_random_uuid(),array[2])->>'status','committed','explicit duplicate exclusion is respected, not chosen silently');
select public.create_student('03e71159-69e9-4387-9b3b-65799d49faf0','df8fcd98-6ece-4f87-b4e9-2f5f3ec8e488',public.create_school_person('03e71159-69e9-4387-9b3b-65799d49faf0','df8fcd98-6ece-4f87-b4e9-2f5f3ec8e488','Inactive test','student'),'B2A-INACTIVE','Old','Test','Old Test');
select public.set_student_status('03e71159-69e9-4387-9b3b-65799d49faf0','df8fcd98-6ece-4f87-b4e9-2f5f3ec8e488',(select id from students where student_code='B2A-INACTIVE'),'inactive');
select is(pg_temp.validate(pg_temp.rows('B2A-INACTIVE'))#>>'{rows,0,errors,0}','existing_code','inactive code cannot be reused');
create temporary table other_scope as select id,school_id from school_locations where school_id<>'df8fcd98-6ece-4f87-b4e9-2f5f3ec8e488' limit 1;
select is(pg_temp.validate(jsonb_set(pg_temp.rows('B2A-X'),'{0,location_id}',to_jsonb((select id::text from other_scope))))#>>'{rows,0,errors,0}','location_invalid','existing cross-school campus denied');
select throws_ok(format('select public.school_student_bulk_validate(%L,pg_temp.rows(''B2A-X''))',(select school_id from other_scope)),'42501','school_authority_required','cross-school authority denied');
-- Force the SECOND insert to fail after the first row has written all four records.
create function pg_temp.fail_second() returns trigger language plpgsql as $$begin if new.student_code='B2A-FORCED' then raise exception 'forced_failure' using errcode='23514';end if;return new;end$$;
create trigger b2a_failure before insert on public.students for each row execute function pg_temp.fail_second();
create temporary table before_failure as select (select count(*) from persons) persons,(select count(*) from students) students,(select count(*) from student_enrollments) enrollments,(select count(*) from student_campus_placements) placements,(select count(*) from pikas_private.student_bulk_requests) journals;
select throws_ok($q$select pg_temp.commit_batch(pg_temp.rows('B2A-ROLLBACK')||jsonb_set(pg_temp.rows('B2A-FORCED'),'{0,source_row}','9'),gen_random_uuid(),array[2,9])$q$,'23514','forced_failure','late second-row failure aborts atomic batch');
select is((select count(*) from persons),(select persons from before_failure),'Person inserts rolled back');
select is((select count(*) from students),(select students from before_failure),'student inserts rolled back');
select is((select count(*) from student_enrollments),(select enrollments from before_failure),'enrollments rolled back');
select is((select count(*) from student_campus_placements),(select placements from before_failure),'placements rolled back');
select is((select count(*) from pikas_private.student_bulk_requests),(select journals from before_failure),'journal rolled back');
drop trigger b2a_failure on public.students;
update pikas_private.application_sessions set started_at=clock_timestamp()-interval '1 hour',last_active_at=clock_timestamp()-interval '31 minutes' where session_id=(select sid from fixture);
select throws_ok($q$select pg_temp.commit_batch(pg_temp.rows('B2A-CREATED'))$q$,'42501','application_session_expired','expired session cannot replay a committed batch');
insert into auth.sessions(id,user_id,created_at,updated_at) select 'b2a00000-0000-4000-8000-000000000003',uid,clock_timestamp(),clock_timestamp() from fixture;
select set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id','b2a00000-0000-4000-8000-000000000003')::text,true) from fixture;
select public.pikas_session_start();
select is(pg_temp.commit_batch(pg_temp.rows('B2A-CREATED')),(select result from successful),'same real user after reauthentication recovers exact original result');
-- Exercise the hard boundary under the new bulk RPC's bounded 30-second statement budget.
create temporary table boundary as select jsonb_agg(jsonb_build_object('source_row',n,'first_name','Boundary','last_name','Local','student_code','B2A-BOUNDARY-'||n,'starts_on',current_date::text)) rows,array_agg(n) included from generate_series(1,200) n;
select is(pg_temp.validate((select rows from boundary))->>'valid','true','all 200 source rows validated');
set local statement_timeout='30s';
create temporary table boundary_result as select pg_temp.commit_batch(rows,gen_random_uuid(),included) result from boundary;
select is((select result->>'status' from boundary_result),'committed','200-row atomic commit fits bounded 30-second statement budget');
select is((select jsonb_array_length(result->'created') from boundary_result),200,'all 200 confirmed rows created');
select is(pg_temp.commit_batch((select jsonb_agg(value order by (value->>'source_row')::int desc) from boundary,jsonb_array_elements(rows)),((select result from boundary_result)->>'request_id')::uuid,(select array_agg(n order by n desc) from generate_series(1,200) n)),(select result from boundary_result),'row and selection order do not change canonical replay');
select is((select count(*)::int from student_wallets w join students s on s.id=w.student_id where s.student_code like 'B2A-BOUNDARY-%'),0,'import creates no wallets');
select is((select count(*)::int from cafeteria_customers c join students s on s.id=c.student_id where s.student_code like 'B2A-BOUNDARY-%'),0,'import grants no cafeteria eligibility');
select is((select count(*)::int from family_student_relationships r join students s on s.id=r.student_id where s.student_code like 'B2A-BOUNDARY-%'),0,'import creates no family links');
set local statement_timeout=0;
-- A second real operator with the SAME shared effective school persona cannot recover A's request.
insert into auth.users(id,email,email_confirmed_at) values('b2a00000-0000-4000-8000-000000000010','bulk-other@example.invalid',now());
insert into persons(id,auth_user_id,display_name) values('b2a00000-0000-4000-8000-000000000011','b2a00000-0000-4000-8000-000000000010','Bulk other local');
insert into pikas_private.platform_memberships(person_id,role_code) values('b2a00000-0000-4000-8000-000000000011','platform_sandbox_operator');
insert into auth.sessions(id,user_id,created_at,updated_at) values('b2a00000-0000-4000-8000-000000000012','b2a00000-0000-4000-8000-000000000010',now(),now());
select set_config('request.jwt.claims','{"sub":"b2a00000-0000-4000-8000-000000000010","role":"authenticated","session_id":"b2a00000-0000-4000-8000-000000000012"}',true);
select public.pikas_session_start();
select public.platform_enter_sandbox_pov(gen_random_uuid(),'03e71159-69e9-4387-9b3b-65799d49faf0','b9496342-5079-46ae-83b8-05c39bcbd7fe','school_admin');
select throws_ok($q$select pg_temp.commit_batch(pg_temp.rows('B2A-CREATED'))$q$,'23505','student_bulk_request_conflict','same persona different real operator cannot recover request');
select is((select count(*)::int from students where student_code='B2A-CREATED'),1,'cross-actor denial adds no duplicate');
select * from finish();
rollback;
